// Takes the first 3 distinct articles among the top 6 hits to read whole; the other hits stay as chunks.
const hits = ($input.first().json.result || []);
const BASE = '/home/node/.n8n-files/wix-docs/';
if (!hits.length) return [{ json: { none: true, path: BASE + '__none__.txt', src: '', chunks: [], rest: [] } }];
const top = hits.map((h) => ({ src: String(h.payload.source), text: String(h.payload.text) }));
const sources = [];
for (const c of top) if (!sources.includes(c.src)) sources.push(c.src);
const chosen = sources.slice(0, 3);
const rest = top.filter((c) => !chosen.includes(c.src));
return chosen.map((src) => ({ json: { src, path: BASE + src, chunks: top.filter((c) => c.src === src).map((c) => c.text), rest } }));

// Build Context (Wix): each of the top 3 articles whole (12,000 characters at most, windowed around the hits), then the other chunks; 60,000 characters in total.
const SYSTEM = ("Support triage agent for Wix ({{ $now.toFormat('yyyy-MM-dd') }}). Use ONLY search_wix_docs context to answer - do not invent configuration values, file paths, commands, or troubleshooting steps beyond what the retrieved context actually states, even if you know the general answer from training. No answer found -> try resolution_specialist once before giving up. cited_source = real doc path from context, or empty string \"\" if none - never invent one, never write an explanatory sentence there. needs_handoff=true only if deferring entirely without trying. If resolution_specialist says it cannot answer / needs review, set needs_human_review=true, confidence=\"low\". No supporting context -> confidence=\"low\", say so.".replace("{{ $now.toFormat('yyyy-MM-dd') }}", new Date().toISOString().slice(0, 10)) + "\n\nReturn only a JSON object with the keys: answer (string), confidence (\"high\", \"medium\" or \"low\"), needs_handoff (boolean), needs_human_review (boolean), cited_source (string). No text outside the JSON.");
const items = $input.all();
const meta = $('Pick Articles').all();
const CAP = 12000;
function win(text, hits) {
  if (text.length <= CAP) return text;
  const pos = hits.map((h) => text.indexOf(h.slice(0, 120))).filter((p) => p >= 0);
  let lo = pos.length ? Math.min(...pos) : 0;
  const hi = pos.length ? Math.max(...pos) + 1000 : 0;
  lo = Math.max(0, lo - Math.max(0, Math.floor((CAP - (hi - lo)) / 2)));
  return text.slice(lo, lo + CAP);
}
const question = $('Finalize Sanitized Text').first().json.normalized_text;
if (meta[0].json.none) {
  return [{ json: { system: SYSTEM, user: 'Question:\n' + question + '\n\nSearch results (the documentation passages found for this question):\n(no passages were found)', retrieval_problem: 'search_empty' } }];
}
const parts = [];
for (let i = 0; i < items.length; i++) {
  const m = meta[i].json;
  let text = '';
  try { text = (await this.helpers.getBinaryDataBuffer(i, 'data')).toString('utf8'); } catch (e) { text = ''; }
  parts.push('[' + m.src + ']\n' + (text.trim() ? win(text, m.chunks) : m.chunks.join('\n')));
}
for (const c of meta[0].json.rest || []) parts.push('[' + c.src + ']\n' + c.text);
const context = parts.join('\n\n---\n\n').slice(0, 60000);
return [{ json: { system: SYSTEM, user: 'Question:\n' + question + '\n\nSearch results (the documentation passages found for this question):\n' + context, retrieval_problem: null } }];

// Extracts the model's JSON reply into { output }. An unusable reply throws, so the error branch answers 503. An empty search becomes a hand-off.
const resp = $input.first().json;
if ($('Build Context').first().json.retrieval_problem === 'search_empty') {
  return [{ json: { output: { answer: '', confidence: 'low', needs_handoff: true, needs_human_review: true, cited_source: '' }, retrieval_problem: 'search_empty', usage: null } }];
}
const raw =resp && resp.choices && resp.choices[0] && resp.choices[0].message ? (resp.choices[0].message.content || '') : '';
const m = String(raw).match(/\{[\s\S]*\}/);
let d = null;
try { d = m ? JSON.parse(m[0]) : null; } catch (e) { d = null; }
if (!d || typeof d !== 'object') {
  throw new Error('answer model returned no usable JSON (' + (resp && (resp.error || resp.message || resp.status) ? JSON.stringify(resp.error || resp.message || resp.status).slice(0, 160) : 'empty reply') + ')');
}
const conf = ['high', 'medium', 'low'].includes(d.confidence) ? d.confidence : 'low';
const answer = typeof d.answer === 'string' ? d.answer : '';
const out = { answer, confidence: answer ? conf : 'low', needs_handoff: d.needs_handoff === true, needs_human_review: d.needs_human_review === true, cited_source: typeof d.cited_source === 'string' ? d.cited_source : '' };
return [{ json: { output: out, retrieval_problem: $('Build Context').first().json.retrieval_problem || null, usage: resp.usage || null } }];
